8	declare_rule! {
9	    /// Disallow duplicate conditions in if-else-if chains
10	    ///
11	    /// if-else-if chains are commonly used when there is a need to execute only one branch
12	    /// (or at most one branch) out of several possible branches, based on certain conditions.
13	    ///
14	    /// Two identical test conditions in the same chain are almost always a mistake in the code.
15	    /// Unless there are side effects in the expressions,
16	    /// a duplicate will evaluate to the same true or false value as the identical expression earlier in the chain,
17	    /// meaning that its branch can never execute.
18	    ///
19	    /// Please note that this rule does not compare conditions from the chain with conditions inside statements
20	    ///
21	    /// ## Examples
22	    ///
23	    /// ### Invalid
24	    ///
25	    /// ```js,expect_diagnostic
26	    /// if (a) {
27	    ///     foo();
28	    /// } else if (b) {
29	    ///     bar();
30	    /// } else if (b) {
31	    ///     baz();
32	    /// }
33	    /// ```
34	    ///
35	    /// ### Valid
36	    ///
37	    /// ```js
38	    /// if (a) {
39	    ///     foo();
40	    /// } else if (b) {
41	    ///     bar();
42	    /// } else if (c) {
43	    ///     baz();
44	    /// }
45	    /// ```
46	    ///
47	    pub NoDuplicateElseIf {
48	        version: "1.6.2",
49	        name: "noDuplicateElseIf",
50	        language: "js",
51	        recommended: true,
52	        sources: &[RuleSource::Eslint("no-dupe-else-if")],
53	    }
54	}
55	
56	impl Rule for NoDuplicateElseIf {
57	    type Query = Ast<JsIfStatement>;
58	    type State = TextRange;
59	
60	    type Signals = Option<Self::State>;
61	    type Options = ();
62	
63	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
64	        let node = ctx.query();
65	        let expr = node.test().ok()?;
66	        let mut conditions_to_check: Vec<AnyJsExpression> = vec![];
67	        conditions_to_check.push(expr.clone());
68	
69	        if let Some(logical_expression) = expr.as_js_logical_expression() {
70	            if let Ok(operator_token) = logical_expression.operator() {
71	                if operator_token == JsLogicalOperator::LogicalAnd {
72	                    conditions_to_check
73	                        .append(&mut split_by_logical_operator_wrapper(operator_token, expr));
74	                }
75	            }
76	        }
77	
78	        let mut list_to_check: Vec<Vec<Vec<AnyJsExpression>>> = conditions_to_check
79	            .into_iter()
80	            .map(|c| {
81	                split_by_logical_operator_wrapper(JsLogicalOperator::LogicalOr, c)
82	                    .into_iter()
83	                    .map(|f| split_by_logical_operator_wrapper(JsLogicalOperator::LogicalAnd, f))
84	                    .collect()
85	            })
86	            .collect();
87	        let mut current = node.syntax().clone();
88	
89	        while let Some(grand_parent_node) = current.grand_parent() {
90	            let Some(if_stmt) = grand_parent_node.cast::<JsIfStatement>() else {
91	                break;
92	            };
93	            if let Ok(expr) = if_stmt.test() {
94	                let current_or_operands: Vec<Vec<AnyJsExpression>> =
95	                    split_by_logical_operator_wrapper(JsLogicalOperator::LogicalOr, expr)
96	                        .into_iter()
97	                        .map(|f| {
98	                            split_by_logical_operator_wrapper(JsLogicalOperator::LogicalAnd, f)
99	                        })
100	                        .collect();
101	
102	                list_to_check = list_to_check
103	                    .iter()
104	                    .map(|or_operands| {
105	                        or_operands
106	                            .iter()
107	                            .filter(|&or_operand| {
108	                                !current_or_operands.iter().any(|current_or_operand| {
109	                                    is_subset(current_or_operand, or_operand)
110	                                })
111	                            })
112	                            .cloned()
113	                            .collect()
114	                    })
115	                    .collect();
116	                if list_to_check.iter().any(|f| f.is_empty()) {
117	                    return node.test().ok().map(|f| f.range());
118	                }
119	            }
120	            current = if_stmt.into_syntax();
121	        }
122	
123	        None
124	    }
125	
126	    fn diagnostic(_: &RuleContext<Self>, text_range: &Self::State) -> Option<RuleDiagnostic> {
127	        Some(RuleDiagnostic::new(
128	            rule_category!(),
129	            text_range,
130	            markup! {
131	                "This branch can never execute. Its condition is a duplicate or covered by previous conditions in the if-else-if chain."
132	            },
133	        ))
134	    }
135	}
136	
137	fn split_by_logical_operator_wrapper(
138	    operator: JsLogicalOperator,
139	    node: AnyJsExpression,
140	) -> Vec<AnyJsExpression> {
141	    let mut result: Vec<AnyJsExpression> = vec![];
142	    split_by_logical_operator(operator, node, &mut result);
143	    result
144	}
145	
146	fn split_by_logical_operator(
147	    operator: JsLogicalOperator,
148	    node: AnyJsExpression,
149	    result: &mut Vec<AnyJsExpression>,
150	) {
151	    let node = node.omit_parentheses();
152	    match &node {
153	        AnyJsExpression::JsLogicalExpression(logic_expression) => {
154	            if let Ok(operator_token) = logic_expression.operator() {
155	                if operator_token != operator {
156	                    result.push(node);
157	                    return;
158	                }
159	            }
160	            if let (Ok(left_node), Ok(right_node)) =
161	                (logic_expression.left(), logic_expression.right())
162	            {
163	                split_by_logical_operator(operator, left_node, result);
164	                split_by_logical_operator(operator, right_node, result);
165	            } else {
166	                result.push(node);
167	            }
168	        }
169	        _ => {
170	            result.push(node);
171	        }
172	    }
173	}
174	
175	fn equal(a: &AnyJsExpression, b: &AnyJsExpression) -> bool {
176	    if a.syntax().kind() != b.syntax().kind() {
177	        return false;
178	    }
179	    if let (Some(a_exp), Some(b_exp)) = (a.as_js_logical_expression(), b.as_js_logical_expression())
180	    {
181	        if a_exp.operator() == b_exp.operator()
182	            && matches!(
183	                a_exp.operator(),
184	                Ok(JsLogicalOperator::LogicalAnd | JsLogicalOperator::LogicalOr)
185	            )
186	        {
187	            match (a_exp.left(), a_exp.right(), b_exp.left(), b_exp.right()) {
188	                (Ok(left_a), Ok(right_a), Ok(left_b), Ok(right_b)) => {
189	                    return (equal(&left_a, &left_b) && equal(&right_a, &right_b))
190	                        || (equal(&left_a, &right_b) && equal(&right_a, &left_b));
191	                }
192	                _ => return false,
193	            }
194	        }
195	        return false;
196	    }
197	    is_node_equal(a.syntax(), b.syntax())
198	}
199	
200	fn is_subset(arr_a: &[AnyJsExpression], arr_b: &[AnyJsExpression]) -> bool {
201	    arr_a.iter().all(|a| arr_b.iter().any(|b| equal(a, b)))
202	}
