14	declare_rule! {
15	    /// Require `new` when throwing an error.
16	    ///
17	    /// While it's possible to instantiate `Error` without using the `new` keyword, it's better to be consistent: modern builtins require `new` to be instantiated.
18	    ///
19	    /// Rule matches errors when their name ends with the word "Error" and the first character is uppercase.
20	    ///
21	    /// ## Examples
22	    ///
23	    /// ### Invalid
24	    ///
25	    /// ```js,expect_diagnostic
26	    /// throw Error();
27	    /// ```
28	    /// ```js,expect_diagnostic
29	    /// throw TypeError('biome');
30	    /// ```
31	    /// ```js,expect_diagnostic
32	    /// throw lib.TypeError();
33	    /// ```
34	    ///
35	    /// ### Valid
36	    ///
37	    /// ```js
38	    /// throw new Error();
39	    /// ```
40	    /// ```js
41	    /// throw new TypeError('biome');
42	    /// ```
43	    /// ```js
44	    /// throw new lib.TypeError();
45	    /// ```
46	    ///
47	    pub UseThrowNewError {
48	        version: "next",
49	        name: "useThrowNewError",
50	        language: "js",
51	        sources: &[RuleSource::EslintUnicorn("throw-new-error")],
52	        recommended: false,
53	        fix_kind: FixKind::Unsafe,
54	    }
55	}
