57	impl Rule for UseThrowNewError {
58	    type Query = Ast<JsCallExpression>;
59	    type State = TokenText;
60	    type Signals = Option<Self::State>;
61	    type Options = ();
62	
63	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
64	        let node = ctx.query();
65	
66	        if !is_in_throw_statement(node) {
67	            return None;
68	        }
69	
70	        let callee = &node.callee().ok()?.omit_parentheses();
71	        let name = match callee {
72	            AnyJsExpression::JsIdentifierExpression(ident_expr) => Some(
73	                ident_expr
74	                    .name()
75	                    .ok()?
76	                    .value_token()
77	                    .ok()?
78	                    .token_text_trimmed(),
79	            ),
80	            AnyJsExpression::JsStaticMemberExpression(member_expr) => Some(
81	                member_expr
82	                    .member()
83	                    .ok()?
84	                    .value_token()
85	                    .ok()?
86	                    .token_text_trimmed(),
87	            ),
88	            _ => None,
89	        }?;
90	
91	        if name.ends_with("Error") && name.chars().next()?.is_uppercase() {
92	            return Some(name);
93	        }
94	
95	        None
96	    }
