98	    fn diagnostic(ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
99	        let node = ctx.query();
100	        let name = state.text();
101	
102	        Some(RuleDiagnostic::new(
103	            rule_category!(),
104	            node.range(),
105	            markup! {
106	                "Use "<Emphasis>"new "{name}"()"</Emphasis>" instead of "<Emphasis>{name}"()"</Emphasis>" when throwing an error."
107	            },
108	        ).note(markup! {
109	            "Instantiate "<Emphasis>"Error"</Emphasis>" with "<Emphasis>"new"</Emphasis>" keyword for consistency with modern builtins."
110	        }))
111	    }
