113	    fn action(ctx: &RuleContext<Self>, _: &Self::State) -> Option<JsRuleAction> {
114	        let node = ctx.query();
115	        let mut mutation = ctx.root().begin();
116	
117	        let new_expression = convert_call_expression_to_new_expression(node)?;
118	
119	        mutation.replace_node::<AnyJsExpression>(node.clone().into(), new_expression.into());
120	
121	        Some(JsRuleAction::new(
