130	fn does_member_contains_call_expression(expr: &AnyJsExpression) -> Option<bool> {
131	    let mut current_node = expr.clone();
132	
133	    loop {
134	        current_node = current_node.omit_parentheses();
135	
136	        if let Some(static_member_expr) = current_node.as_js_static_member_expression() {
137	            current_node = static_member_expr.object().ok()?.clone();
138	        } else if current_node.as_js_call_expression().is_some() {
139	            return Some(true);
140	        } else {
141	            return None;
142	        }
143	    }
144	}
