146	pub(crate) fn convert_call_expression_to_new_expression(
147	    expr: &JsCallExpression,
148	) -> Option<JsNewExpression> {
149	    let mut callee = expr.callee().ok()?;
150	    let leading_trivia_pieces = callee.syntax().first_leading_trivia()?.pieces();
151	
152	    // To use `new` keyword, we need to wrap the callee in parentheses if it contains a call expression.
153	    // Example: `foo().bar()` -> `new (foo().bar())`
154	    if !JsParenthesizedExpression::can_cast(callee.syntax().kind())
155	        && does_member_contains_call_expression(&callee).is_some()
156	    {
157	        callee = AnyJsExpression::JsParenthesizedExpression(make::js_parenthesized_expression(
158	            make::token(T!['(']),
159	            callee,
160	            make::token(T![')']),
161	        ));
162	    }
163	
164	    let new_token = make::token(T![new])
165	        .with_leading_trivia_pieces(leading_trivia_pieces)
166	        .with_trailing_trivia([(TriviaPieceKind::Whitespace, " ")]);
167	
168	    callee = callee.with_leading_trivia_pieces([])?;
169	
170	    Some(
171	        make::js_new_expression(new_token, callee)
172	            .with_arguments(expr.arguments().ok()?)
173	            .build(),
174	    )
175	}
