177	/// Checks if the given expression is inside a `throw` statement.
178	fn is_in_throw_statement(expr: &JsCallExpression) -> bool {
179	    expr.syntax()
180	        .ancestors()
181	        .skip(1)
182	        .find(|ancestor| ancestor.kind() != JsSyntaxKind::JS_PARENTHESIZED_EXPRESSION)
183	        .is_some_and(|ancestor| ancestor.kind() == JsSyntaxKind::JS_THROW_STATEMENT)
184	}
